 function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
 function render(){ $('coins').textContent=s.coins;$('milk').textContent=s.milk;$('day').textContent=s.day;$('energyText').textContent=`${s.energy} / ${s.maxEnergy}`;$('energyBar').style.width=`${s.energy/s.maxEnergy*100}%`;$('level').textContent=s.level;$('growthText').textContent=`${s.growth} / 12 л`;$('growthBar').style.width=`${s.growth/12*100}%`;$('herdCount').textContent=`${s.cows} ${s.cows===1?'коровка':'коровки'}`;
 $('cowList').innerHTML=Array.from({length:s.cows},(_,i)=>`<div class="cow-row"><div class="cow-icon">🐮</div><div class="cow-meta"><strong>${['Звёздочка','Ромашка','Булочка'][i%3]}</strong><small>${s.fed?'Сыто улыбается':'Ждёт свежего сена'} · взрослая коровка</small></div><span class="status ${s.fed?'':'ready'}">${s.fed?'СЫТА':'ГОЛОДНА'}</span></div>`).join('');
 $('feedBtn').disabled=s.fed||s.energy<1;$('milkBtn').disabled=!s.fed||s.energy<1;$('sellBtn').disabled=s.milk<1;$('dayBtn').disabled=s.energy===s.maxEnergy&&!s.fed;
-$('pastureBtn').disabled=s.coins<25||s.pasture>=3;$('pastureBtn').textContent=s.pasture>=3?'Улучшено ✓':`Улучшить · ${25+s.pasture*15} 🪙`;$('bucketBtn').disabled=s.coins<40||s.bucket;$('bucketBtn').textContent=s.bucket?'Куплено ✓':'Купить · 40 🪙';$('cowBtn').disabled=s.coins<60||s.cows>=3;$('cowBtn').textContent=s.cows>=3?'Стадо полное ✓':'Пригласить · 60 🪙';$('barnBtn').disabled=s.coins<45||s.barn;$('barnBtn').textContent=s.barn?'Улучшено ✓':'Улучшить · 45 🪙';$('log').innerHTML=s.log.map(x=>`<p>• ${x}</p>`).join('');
+$('pastureBtn').disabled=s.coins<25+s.pasture*15||s.pasture>=3;$('pastureBtn').textContent=s.pasture>=3?'Улучшено ✓':`Улучшить · ${25+s.pasture*15} 🪙`;$('bucketBtn').disabled=s.coins<40||s.bucket;$('bucketBtn').textContent=s.bucket?'Куплено ✓':'Купить · 40 🪙';$('cowBtn').disabled=s.coins<60||s.cows>=3;$('cowBtn').textContent=s.cows>=3?'Стадо полное ✓':'Пригласить · 60 🪙';$('barnBtn').disabled=s.coins<45||s.barn;$('barnBtn').textContent=s.barn?'Улучшено ✓':'Улучшить · 45 🪙';$('log').innerHTML=s.log.map(x=>`<p>• ${x}</p>`).join('');
 const scale=1+Math.min(.18,(s.level-1)*.045);$('avatarWrap').style.transform=`translateX(-20%) scale(${scale})`;$('goal').textContent=s.earnedToday>=20?'Цель дня выполнена! ✓':`Цель: заработать 20 🪙 (${s.earnedToday}/20)`;save()}
 function spendEnergy(n=1){if(s.energy<n){toast('Нужно отдохнуть до нового дня 🌙');return false}s.energy-=n;return true}
 $('feedBtn').onclick=()=>{if(s.fed||!spendEnergy())return;s.fed=true;note('Свежее сено и яблочки — стадо довольно.');toast('Все коровки накормлены 🌾');render()};
 $('milkBtn').onclick=()=>{if(!s.fed){toast('Сначала покорми коровок 🌾');return}if(!spendEnergy())return;const amount=s.cows*(2+s.pasture);s.milk+=amount;s.growth+=amount;let leveled=false;while(s.growth>=12){s.growth-=12;s.level++;leveled=true}note(`Утренняя дойка принесла ${amount} л свежего молока.`);if(leveled){note(`Молочная сила Милы выросла до ${s.level}-го уровня!`);toast('Уровень молочной силы вырос! ✨')}else toast(`Собрано ${amount} л молока 🥛`);s.fed=false;render()};

